INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES
('2026-06-01-cloud-native-ai-infra-digest', 'Cloud Native and AI Infrastructure Digest: June 1, 2026', 'Fresh analysis covers the Miasma npm supply-chain attack, vLLM serving on DGX Spark, vLLM-Omni GGUF quantization, and CNCF guidance on dynamic Swift service configuration.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"miasma-turns-npm-trusted-publishing-against-red-hat-cloud-packages"},"content":[{"type":"text","text":"Miasma turns npm trusted publishing against Red Hat cloud packages"}]},{"type":"paragraph","content":[{"type":"text","text":"SafeDep and Wiz disclosed Miasma on June 1: an npm supply-chain attack against packages in the "},{"type":"text","text":"@redhat-cloud-services","marks":[{"type":"code"}]},{"type":"text","text":" namespace."}]},{"type":"paragraph","content":[{"type":"text","text":"The attacker did not bypass provenance. They made provenance point at the wrong thing. According to SafeDep, short-lived "},{"type":"text","text":"oidc-*","marks":[{"type":"code"}]},{"type":"text","text":" branches were added to three RedHatInsights repositories, trusted-publishing workflows were changed, and modified packages were pushed with valid npm provenance. The missing control was branch authorization: the registry could prove which repository and workflow produced the artifact, but not that the publish came from a protected branch operators trusted."}]},{"type":"paragraph","content":[{"type":"text","text":"The malicious packages executed during "},{"type":"text","text":"preinstall","marks":[{"type":"code"}]},{"type":"text","text":". They downloaded Bun when it was not already present, then scanned for cloud, Kubernetes, npm, GitHub, Vault, and password-manager credentials. Wiz says most affected versions had been revoked by its 13:00 UTC update, with two still remaining at publication time."}]},{"type":"paragraph","content":[{"type":"text","text":"Platform teams should treat trusted-publishing configuration as production infrastructure. Bind publish workflows to protected branches or environments wherever the registry supports it, and block known-bad package versions before CI can run lifecycle scripts."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"SafeDep","marks":[{"type":"link","attrs":{"href":"https://safedep.io/redhat-cloud-services-hit-by-mini-shai-hulud-npm-worm/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"Wiz","marks":[{"type":"link","attrs":{"href":"https://www.wiz.io/blog/miasma-supply-chain-attack-targeting-redhat-npm-packages","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"vllm-publishes-dgx-spark-serving-guidance-for-nemotron-3-super"},"content":[{"type":"text","text":"vLLM publishes DGX Spark serving guidance for Nemotron-3-Super"}]},{"type":"paragraph","content":[{"type":"text","text":"The vLLM project published a June 1 deployment guide for running "},{"type":"text","text":"nvidia/NVIDIA-Nemotron-3-Super-120B-A12B-NVFP4","marks":[{"type":"code"}]},{"type":"text","text":" through vLLM on NVIDIA DGX Spark."}]},{"type":"paragraph","content":[{"type":"text","text":"The guide is useful because DGX Spark is not a normal data-center GPU target. Its GB10 Grace Blackwell SoC exposes a unified 128 GB CPU/GPU memory pool, so vLLM settings such as "},{"type":"text","text":"--gpu-memory-utilization","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--max-model-len","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"--max-num-seqs","marks":[{"type":"code"}]},{"type":"text","text":" affect the operating system, container runtime, model weights, and KV cache together."}]},{"type":"paragraph","content":[{"type":"text","text":"The published example uses the OpenAI-compatible vLLM server image, "},{"type":"text","text":"--max-model-len 131072","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--gpu-memory-utilization 0.85","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--max-num-seqs 4","marks":[{"type":"code"}]},{"type":"text","text":", and model-specific parser flags. vLLM reports a five-scenario single-Spark evaluation with median decode throughput in the 22.7 to 23.7 tokens/sec range after warm-up, and explicitly frames the result as recipe-specific rather than a general DGX Spark ceiling."}]},{"type":"paragraph","content":[{"type":"text","text":"This matters for local and small-batch inference work because the post turns \"will this fit?\" into a runbook shape: pin an image, pre-stage weights, warm JIT paths before first use, and watch KV-cache plus TTFT metrics from "},{"type":"text","text":"/metrics","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM","marks":[{"type":"link","attrs":{"href":"https://vllm.ai/blog/2026-06-01-vllm-dgx-spark","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"vllm-omni-documents-gguf-quantization-for-diffusion-serving"},"content":[{"type":"text","text":"vLLM-Omni documents GGUF quantization for diffusion serving"}]},{"type":"paragraph","content":[{"type":"text","text":"The vLLM-Omni documentation added June 1 guidance for GGUF quantization in diffusion-serving paths."}]},{"type":"paragraph","content":[{"type":"text","text":"The implementation loads pre-quantized diffusion transformer weights from GGUF while keeping the rest of the pipeline on the base Hugging Face checkpoint for tokenizer, text encoder, scheduler, and VAE state. The docs list validated adapter paths for Qwen-Image, Z-Image, and FLUX.2-klein, while multi-stage omni, TTS, BAGEL, and GLM-Image paths remain unvalidated or require model-specific adapters."}]},{"type":"paragraph","content":[{"type":"text","text":"For serving, the documented online path passes "},{"type":"text","text":"--diffusion-quantization-config ''{\"method\":\"gguf\",\"gguf_model\":\"...\"}''","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"vllm serve --omni","marks":[{"type":"code"}]},{"type":"text","text":". Hardware support is documented for NVIDIA Ampere, Ada/Hopper, and Blackwell GPUs, with ROCm marked unverified and Ascend marked unsupported."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical value is clearer failure behavior: unsupported models should fail with an adapter error instead of silently using a generic tensor-name mapper."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM-Omni","marks":[{"type":"link","attrs":{"href":"https://docs.vllm.ai/projects/vllm-omni/en/latest/user_guide/quantization/gguf/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"cncf-covers-dynamic-configuration-patterns-for-swift-services-on-kubernetes"},"content":[{"type":"text","text":"CNCF covers dynamic configuration patterns for Swift services on Kubernetes"}]},{"type":"paragraph","content":[{"type":"text","text":"CNCF published a June 1 technical post on Swift Configuration for cloud native Swift services."}]},{"type":"paragraph","content":[{"type":"text","text":"The post focuses on operational configuration mechanics rather than language marketing: ordered configuration providers, dot-notation keys that map across files and environment variables, ConfigMap-style file reloading, and immutable snapshots so a request does not observe half of one configuration version and half of another."}]},{"type":"paragraph","content":[{"type":"text","text":"The Kubernetes-specific detail is the torn-read problem during hot reload. Swift Configuration''s provider model replaces a complete snapshot atomically and keeps the previous valid snapshot when a reload is malformed, which is the behavior platform teams generally want from ConfigMap-mounted runtime configuration."}]},{"type":"paragraph","content":[{"type":"text","text":"This is niche, but it is technically useful for teams running Swift services on Kubernetes because it gives the runtime a first-class model for precedence, reloads, and consistent reads instead of ad hoc "},{"type":"text","text":"ProcessInfo.environment","marks":[{"type":"code"}]},{"type":"text","text":" plus hand-rolled file parsing."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"CNCF","marks":[{"type":"link","attrs":{"href":"https://www.cncf.io/blog/2026/06/01/dynamic-configuration-for-cloud-native-swift-services/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"}]}', 1780272000000, 1790105224000),
('2026-09-18-gloo-interrupted-validation', 'Gloo Gateway Fixes Interrupted Validation That Could Drop Listeners', 'Four Gloo Gateway patch releases stop interrupted Envoy validation from being cached as a configuration failure, which could remove a listener during WAF validation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gloo Gateway could mistake an interrupted Envoy validation process for invalid configuration. That false result was then cached and acted upon like a genuine rejection. In the most severe documented case, an interruption during WAF plugin validation could remove a listener with no automatic recovery path."}]},{"type":"paragraph","content":[{"type":"text","text":"The fix distinguishes a cancelled context or killed Envoy validation process from a completed validation failure. Gloo now discards the incomplete translation instead of publishing it or writing its status. The previously published xDS snapshot remains in the cache until a later translation completes successfully. A genuine configuration rejection still follows the existing rejection path."}]},{"type":"paragraph","content":[{"type":"text","text":"Solo shipped the correction on 18 September 2026 in "},{"type":"text","text":"1.19.23","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.19.23","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"1.20.25","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.20.25","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"1.21.16","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.21.16","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", and "},{"type":"text","text":"1.22.4","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.22.4","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":". The project has not stated an earliest affected version, so those fixed branches should not be read as a complete vulnerable-version range."}]},{"type":"paragraph","content":[{"type":"text","text":"The change also separates operational interruption signals from bad configuration. "},{"type":"text","text":"api.gloo.solo.io/translator/validation_interruption_skips","marks":[{"type":"code"}]},{"type":"text","text":", labelled by "},{"type":"text","text":"proxy_name","marks":[{"type":"code"}]},{"type":"text","text":", counts translations skipped while retaining the existing xDS snapshot. Admission interruptions increment "},{"type":"text","text":"validation.gateway.solo.io/resources_validation_incomplete","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"resources_rejected","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Operators using Gloo’s Envoy validation path, especially deployments with WAF configuration, should upgrade to the fixed patch for their release line. Alert on sustained increases in "},{"type":"text","text":"validation_interruption_skips","marks":[{"type":"code"}]},{"type":"text","text":": they indicate that a proxy is retaining its previous configuration because new translations are not completing."}]}]}', 1789689600000, 1789816434000),
('kubernetes-1-36-sneak-peek', 'Kubernetes 1.36 Sneak Peek: DRA Goes GA, Ingress-NGINX Retires, HPA Scales to Zero', 'Kubernetes v1.36, releasing April 22, finalizes DRA to GA, graduates User Namespaces, enables HPA scale-to-zero by default, and formally retires Ingress-NGINX.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.36 drops on April 22, 2026. It''s a big one. Several features that have been cooking for years are finally landing, and one major deprecation will force migration plans."}]},{"type":"heading","attrs":{"level":2,"id":"dra-goes-ga"},"content":[{"type":"text","text":"DRA Goes GA"}]},{"type":"paragraph","content":[{"type":"text","text":"Four Dynamic Resource Allocation (DRA) enhancements are graduating to GA. After years of development, hardware-aware scheduling is now a first-class, production-ready feature in upstream Kubernetes. GPUs and other accelerators are finally manageable through standard Kubernetes APIs. No more relying on vendor-specific device plugins alone."}]},{"type":"heading","attrs":{"level":2,"id":"ingress-nginx-formally-retired"},"content":[{"type":"text","text":"Ingress-NGINX Formally Retired"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes SIG Network and the Security Response Committee have formally retired the Ingress-NGINX controller as of March 24, 2026. There will be no further releases, bugfixes, or security updates. Existing deployments continue to function and artifacts remain available, but this cements Gateway API as the standard ingress path going forward."}]},{"type":"heading","attrs":{"level":2,"id":"hpa-scale-to-zero-enabled-by-default"},"content":[{"type":"text","text":"HPA Scale-to-Zero Enabled by Default"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"HPAScaleToZero","marks":[{"type":"code"}]},{"type":"text","text":" feature gate, which has been sitting in alpha since Kubernetes v1.16, is now enabled by default. The Horizontal Pod Autoscaler can finally scale workloads down to zero replicas without additional configuration."}]},{"type":"heading","attrs":{"level":2,"id":"additional-highlights"},"content":[{"type":"text","text":"Additional Highlights"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User Namespaces","marks":[{"type":"bold"}]},{"type":"text","text":" graduate to stable, providing better pod isolation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mutating Admission Policies","marks":[{"type":"bold"}]},{"type":"text","text":" graduate to stable"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"gitRepo volume plugin","marks":[{"type":"bold"}]},{"type":"text","text":" is permanently disabled with no opt-back-in"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"externalIPs","marks":[{"type":"bold"}]},{"type":"text","text":" field in Service spec is being deprecated, with full removal planned for v1.43"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"18 enhancements moving to stable in total"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Still on Ingress-NGINX? Start planning your Gateway API migration now. HPA scale-to-zero landing as default changes the economics of event-driven and batch workloads. And DRA going GA means hardware-aware scheduling is production-ready upstream, not a vendor add-on."}]}]}', 1774828800000, 1775217302000),
('kyverno-graduates-cncf', 'Kyverno Graduates from CNCF — Policy-as-Code Goes Mainstream', 'Kyverno reaches CNCF Graduated status with full CEL adoption, completing its journey from Kubernetes admission controller to a broader policy engine for the cloud native stack.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno has reached CNCF Graduated status, the highest maturity level in the CNCF project lifecycle. The announcement came at KubeCon + CloudNativeCon Europe 2026 in Amsterdam on March 24, 2026."}]},{"type":"heading","attrs":{"level":2,"id":"what-graduation-actually-requires"},"content":[{"type":"text","text":"What Graduation Actually Requires"}]},{"type":"paragraph","content":[{"type":"text","text":"This isn''t a rubber stamp. Graduation required a third-party security audit and a full security assessment led by CNCF TAG Security & Compliance. These validate that the project can handle production workloads and has a defensible security posture."}]},{"type":"heading","attrs":{"level":2,"id":"full-cel-adoption"},"content":[{"type":"text","text":"Full CEL Adoption"}]},{"type":"paragraph","content":[{"type":"text","text":"With its latest release, Kyverno has fully adopted Common Expression Language (CEL), matching the direction Kubernetes itself is heading for admission controls."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical upside: Kyverno policies and Kubernetes ValidatingAdmissionPolicies now use the same expression language. Platform teams don''t need to context-switch between two policy syntaxes anymore."}]},{"type":"heading","attrs":{"level":2,"id":"beyond-kubernetes"},"content":[{"type":"text","text":"Beyond Kubernetes"}]},{"type":"paragraph","content":[{"type":"text","text":"Kyverno started as a Kubernetes-native admission controller, but it''s grown into something broader. Declarative policies are now usable across a wide range of payloads and enforcement points across the cloud native stack."}]},{"type":"heading","attrs":{"level":2,"id":"growth-since-2020"},"content":[{"type":"text","text":"Growth Since 2020"}]},{"type":"paragraph","content":[{"type":"text","text":"Since joining CNCF in 2020, Kyverno has gone from 574 GitHub stars to more than 9,000. The contributor base has expanded significantly, with adopters spanning startups to large enterprises."}]},{"type":"paragraph","content":[{"type":"text","text":"The CEL alignment is really the key story here. As Kubernetes moves toward CEL-based admission control, Kyverno''s adoption of the same expression language makes it a natural extension of the platform rather than a competing paradigm. That''s a smart bet on where the ecosystem is going."}]}]}', 1774310400000, 1775217302000);
